use std::fs

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut ks: Vec<int> = []
    let mut vs: Vec<int> = []
    let mut cap: int = 0
    let mut first = true
    for line in text.lines() {
        let t = line.trim()
        if t.len() == 0 {
            continue
        }
        if first {
            cap = t.parse::<int>().unwrap_or(1)
            first = false
            continue
        }
        let parts: Vec<string> = t.split(" ").map(|s| s.to_string()).collect()
        let cmd = parts[0]
        if cmd == "put" {
            let k = parts[1].parse::<int>().unwrap_or(0)
            let v = parts[2].parse::<int>().unwrap_or(0)
            let mut nk: Vec<int> = [k]
            let mut nv: Vec<int> = [v]
            let n: int = ks.len() as int
            for i in 0..n {
                if ks[i as usize] != k {
                    nk.push(ks[i as usize])
                    nv.push(vs[i as usize])
                }
            }
            if nk.len() as int > cap {
                let last = nk.len() - 1
                let ek = nk[last]
                nk.pop()
                nv.pop()
                println("evict ${ek}")
            }
            ks = nk
            vs = nv
        } else if cmd == "get" {
            let k = parts[1].parse::<int>().unwrap_or(0)
            let mut found = -1
            let mut nk: Vec<int> = []
            let mut nv: Vec<int> = []
            let n: int = ks.len() as int
            for i in 0..n {
                if ks[i as usize] == k {
                    found = vs[i as usize]
                }
            }
            if found != -1 {
                nk.push(k)
                nv.push(found)
            }
            for i in 0..n {
                if ks[i as usize] != k {
                    nk.push(ks[i as usize])
                    nv.push(vs[i as usize])
                }
            }
            ks = nk
            vs = nv
            println("${found}")
        } else if cmd == "keys" {
            if ks.len() == 0 {
                println("<empty>")
            } else {
                let mut s = ""
                let n: int = ks.len() as int
                for i in 0..n {
                    if s.len() > 0 {
                        s = s + " "
                    }
                    s = s + "${ks[i as usize]}"
                }
                println("${s}")
            }
        }
    }
}

